      section2Body: '了解女性教法学，可以让人在身体经历特定阶段（月经、怀孕、产后、绝经）时，更加安心地进行宗教实践，不再困惑。它也有助于分清哪些属于义务，哪些属于豁免，哪些只是建议。',
