      section4Body: '关于周期的医学信息（时长、症状、激素阶段）与由此引出的宗教规则（洁净、礼拜、斋戒），遵循的是两种不同的逻辑：一个描述生理现象，另一个界定精神实践的框架。两者可以互为补充，但不应混为一谈。',
      visual2Title: '两种互补的视角',
      visual2Text: '周期的医学记录与由此而来的宗教标志，各自都能提供有用的参考。',
      tip2Title: '小贴士',
