    section1Body: 'Kvinders fiqh er det felt inden for islamisk jurisprudens (fiqh), der beskæftiger sig med praktiske spørgsmål om kvinders krop og gudsdyrkelse. Det hjælper med at forstå, hvordan man forener det daglige religiøse liv med de forskellige faser i den kvindelige cyklus.',
