    section1Body2: 'Fiqh er et felt af juridisk fortolkning: nogle spørgsmål er genstand for forskellige meninger afhængigt af de lærde og retsskoler, uden at nogen enkelt mening i sig selv er absolut.',
    section2Body: 'At forstå kvinders fiqh gør det muligt at leve sin religiøse praksis med større ro, uden forvirring, i perioder hvor kroppen gennemgår specifikke faser (menstruation, graviditet, barsel, overgangsalder). Det hjælper også med at skelne mellem, hvad der er en forpligtelse, en fritagelse eller en simpel anbefaling.',
    visual1Title: 'En mere fredfyldt religiøs praksis',
    visual1Text: 'At vide, hvad der forventes på hvert trin i cyklussen, gør det muligt at nærme sig sin tro med større tillid.',
    section3Body: 'En madhab betegner en retsskole, dvs. en struktureret metode, som lærde bruger til at fortolke religiøse kilder (Koranen, Sunnah, konsensus, ræsonnement) og besvare praktiske spørgsmål i dagliglivet. Der findes flere skoler, fordi de lærde ikke altid har fulgt den samme metodologi eller fortolket de samme tekster på samme måde.',
    section3Body2: 'Derfor kan nogle spørgsmål relateret til menstruation, rituel renhed, bøn eller faste være genstand for forskellige meninger afhængigt af de lærde, man konsulterer. En meningsforskel betyder ikke, at én mening er "forkert": den afspejler forskellige metodologier og læsninger af de samme kilder.',
    tip1Title: 'Godt at vide',
    tip1Text: 'Det er almindeligt at følge den fremgangsmåde eller den madhab, der traditionelt følges i ens familie eller lokalsamfund.',
    noteTitle: 'Bemærk venligst',
    noteText: 'Når en specifik religiøs situation forbliver usikker, er det fuldt ud passende at bede om en kvalificeret lærds mening.',
    section4Body: 'Medicinsk information om cyklussen (varighed, symptomer, hormonelle faser) og de religiøse regler, der følger heraf (renhed, bøn, faste), svarer til to forskellige logikker: den ene beskriver et biologisk fænomen, den anden definerer en ramme for åndelig praksis. De to kan supplere hinanden, men må ikke forveksles.',
    visual2Title: 'To komplementære perspektiver',
    visual2Text: 'Medicinsk overvågning af cyklussen og de religiøse markører, der følger heraf, giver hver især nyttig indsigt.',
