    section2Body: 'කාන්තා ෆික්හ් තේරුම් ගැනීම, ශරීරය විශේෂ අවධි (ඔසප්, ගර්භණී කාලය, ප්‍රසූතියෙන් පසු, ඔසප් නැවතීම) හරහා ගමන් කරන අවස්ථාවල, ව්‍යාකූලත්වයකින් තොරව, වඩා සන්සුන්කමින් තම ආගමික පුරුදු ගත කිරීමට හැකියාව ලබා දෙයි. එය බැඳීමක්, නිදහස් කිරීමක් හෝ සරල නිර්දේශයක් යටතට වැටෙන්නේ කුමක්දැයි වෙන්කර හඳුනාගැනීමටද උපකාරී වේ.',
