    section1Body2: 'ฟิกฮ์เป็นสาขาของการตีความทางกฎหมาย: บางประเด็นมีความเห็นต่างกันตามผู้รู้และสำนักคิด โดยไม่มีความเห็นใดเป็นสัมบูรณ์ด้วยตัวเอง',
