    visual1Text: 'იმის ცოდნა, რა მოსალოდნელია ციკლის თითოეულ ეტაპზე, საშუალებას იძლევა საკუთარ რწმენას უფრო თავდაჯერებულად მივუდგეთ.',
    section3Body: 'მაზჰაბი ნიშნავს სამართლებრივი აზროვნების სკოლას, ანუ სტრუქტურირებულ მეთოდს, რომელსაც მეცნიერები იყენებენ რელიგიური წყაროების (ყურანი, სუნნა, კონსენსუსი, მსჯელობა) ინტერპრეტაციისთვის და ყოველდღიური ცხოვრების პრაქტიკულ კითხვებზე პასუხის გასაცემად. არსებობს რამდენიმე სკოლა, რადგან მეცნიერები ყოველთვის ერთსა და იმავე მეთოდოლოგიას არ მისდევდნენ და იმავე ტექსტებს ერთნაირად არ ინტერპრეტირებდნენ.',
    section3Body2: 'სწორედ ამიტომ ზოგი საკითხი, რომელიც მენსტრუაციას, რიტუალურ სისუფთავეს, ლოცვასა თუ მარხვას უკავშირდება, შეიძლება კონსულტირებული მეცნიერების მიხედვით განსხვავებულ მოსაზრებებს ექვემდებარებოდეს. მოსაზრებების განსხვავება არ ნიშნავს, რომ ერთი მოსაზრება „მცდარია“: ის ასახავს ერთი და იმავე წყაროების განსხვავებულ მეთოდოლოგიებსა და წაკითხვებს.',
    tip1Title: 'კარგია ვიცოდეთ',
    tip1Text: 'გავრცელებულია იმ მიდგომის ან მაზჰაბის დაცვა, რომელსაც ტრადიციულად საკუთარი ოჯახი ან საზოგადოება მისდევს.',
    noteTitle: 'გაითვალისწინეთ',
    noteText: 'როცა კონკრეტული რელიგიური სიტუაცია გაურკვეველი რჩება, სრულიად სათანადოა კვალიფიციური მეცნიერის აზრის კითხვა.',
    section4Body: 'ციკლის შესახებ სამედიცინო ინფორმაცია (ხანგრძლივობა, სიმპტომები, ჰორმონული ფაზები) და მისგან გამომდინარე რელიგიური წესები (სისუფთავე, ლოცვა, მარხვა) ორ განსხვავებულ ლოგიკას პასუხობს: ერთი ბიოლოგიურ მოვლენას აღწერს, მეორე სულიერი პრაქტიკის ჩარჩოს განსაზღვრავს. ორივეს შეუძლია ერთმანეთის შევსება, მაგრამ არ უნდა აგვერიოს.',
    visual2Title: 'ორი ურთიერთშემავსებელი პერსპექტივა',
    visual2Text: 'ციკლის სამედიცინო კონტროლი და მისგან გამომდინარე რელიგიური მარკერები თითოეული სასარგებლო წარმოდგენას გვაძლევს.',
    tip2Title: 'კარგია ვიცოდეთ',
    tip2Text: 'ჯანდაცვის სპეციალისტს შეუძლია სამედიცინო კითხვებზე გიპასუხოთ; კვალიფიციური მეცნიერი რელიგიურ საკითხებში საორიენტაციო წყაროდ რჩება.',
    section5Body: 'AWA მომხმარებლებს ეხმარება თავიანთი ციკლის გაგებაში, ჯანმრთელობისა და რელიგიური პრაქტიკის გასაყარზე, საგანმანათლებლო მიდგომით, რომელიც სკოლებს შორის განსხვავებებს პატივს სცემს.',
