    section1Body: 'Կանանց ֆիքհը իսլամական իրավագիտության (ֆիքհ) այն ոլորտն է, որը զբաղվում է կանանց մարմնին և պաշտամունքին առնչվող գործնական հարցերով: Այն օգնում է հասկանալ, թե ինչպես համադրել առօրյա կրոնական կյանքը կանացի ցիկլի տարբեր փուլերի հետ:',
